customMethods.script:
lotsDeleted = []
lotsNotDeleted = []
for lot in self.view.custom.table.selection.data:
	retVal, msg = system.kanoa.lot.deleteLot(lot['lotId'], self.view.custom.security.userId)

	if msg:	
		lotsNotDeleted.append({'lotName': lot['lotName'], 'msg': msg})
	else: 
		lotsDeleted.append(lot['lotName'])

self.getData()

if len(lotsNotDeleted) > 0:
	msg = 'The following lots were not deleted.'
	lots = ", ".join(lotsDeleted)
	for info in lotsNotDeleted:
		msg += '\n%s %s'%(info['lotName'], info['msg'])

	system.perspective.sendMessage('showWarningToast', {'message': msg})
else:
	lots = ", ".join(lotsDeleted)
	system.perspective.sendMessage('showSuccessfulToast', {'message': '%s %s been deleted'%(lots, 'have' if len(lotsDeleted) > 1 else 'has')})

return

